\implies a^2 - ac\cos B &= b^2 + bc\cos A
\implies a^2 + (a^2 + c^2 -2ac\cos B) &= 2b^2 + c^2 + 2bc\cos A
\implies a^2 + b^2 &= 2b^2 + c^2 + 2bc\cos A
\implies b^2 + c^2 - 2bc\cos A &= b^2 + c^2 + 2bc\cos A
\implies \cos A &= 0
\implies A &= 90^{\circ}
\end{align*}

