[asy]
pair excentre(pair A, pair B, pair C) {
  return((-abs(B - C)*A + abs(C - A)*B + abs(A - B)*C)/(-abs(B - C) + abs(C - A) + abs(A - B)));
};

pair mixtilinearcirclecenter(pair A, pair B, pair C) {
  pair I, D, E;
  I = incenter(A,B,C);
  D = extension(A, B, I, rotate(90)*(A - I) + I);
  E = extension(A, C, I, rotate(90)*(A - I) + I);
  return(extension(D, rotate(90)*(A - D) + D, E, rotate(90)*(A - E) + E));
};

real mixtilinearcircleradius(pair A, pair B, pair C) {
  pair I, D, E, O;
  I = incenter(A,B,C);
  D = extension(A, B, I, rotate(90)*(A - I) + I);
  E = extension(A, C, I, rotate(90)*(A - I) + I);
  return(abs(mixtilinearcirclecenter(A,B,C) - D));
};

path mixtilinearcircle(pair A, pair B, pair C) {
  return(Circle(mixtilinearcirclecenter(A,B,C),mixtilinearcircleradius(A,B,C)));
};

pair mixtilinearcircletangentpoint(pair A, pair B, pair C) {
  pair[] R;
  R[0] = abs(circumcenter(A,B,C) - A);
  R[1] = mixtilinearcircleradius(A,B,C);
  return((R[0]*mixtilinearcirclecenter(A,B,C) - R[1]*circumcenter(A,B,C))/(R[0] - R[1]));
};

